function wizardSteps(a){const b=baseSteps(a);return a._firstTime?[6,...b]:b}
function baseSteps(a){return a.type==='juken'?[0,3,5]:a.type==='habit'?[0,1,3,4,5]:a.type==='task'?(a._skipMat?[0,1,5]:[0,1,3,5]):a._skipMat?[0,1,2,5]:[0,1,2,3,5]}
function nextStep(w,dir){const st=wizardSteps(w.input),i=st.indexOf(w.step);return st[Math.min(st.length-1,Math.max(0,(i<0?0:i)+dir))]}
function jukenInput(a){const j=a.juken,end=C.add(S.date,180),exam=(j.examYm||'')+'-15';return {...a,title:'大学受験'+(j.univ?'：'+j.univ:''),target:a.target||'',start:S.date,goal:exam>S.date&&exam<end?exam:end,materials:[],juken:{band:j.band,examYm:j.examYm,univ:j.univ,dev:j.dev,mockType:j.mockScore===''||j.mockScore==null?'':j.mockType,mockScore:j.mockScore===''?null:j.mockScore,others:j.others,subjects:j.subjects,owned:j.owned,route:j.route||'',autoTasks:true}}}
function badge(t,cls=''){return '<span class="chip-s '+cls+'">'+esc(t)+'</span>'}
function itemState(it,today){return it.finished?badge('終わった','ok'):it.locked?badge('講師が調整','wait'):it.hold?badge('保留','late'):it.replaced?badge('手持ちを使う','ok'):it.from>today?badge('これから'):it.to<today?badge('期間が過ぎた','late'):badge('取り組み中','wait')}
function roadmapHtml(rm){const P=(typeof JC!=='undefined'&&JC&&JC.PREP)||'';let shown=false;return rm.map(m=>{let t=m.text||'';if(P&&t.indexOf(P)===0){t=t.slice(P.length).replace(/^　/,'');const head=shown?'':'<p class="caption">'+esc(P)+'</p>';shown=true;return head+'<p><b>'+esc(m.month)+'</b><br>'+esc(t||'（教材なし）')+'</p>'}return '<p><b>'+esc(m.month)+'</b><br>'+esc(t)+'</p>'}).join('')}
function upperSummary(p){const j=p.juken;return card('志望校から逆算した計画','<p><b>'+esc(j.bandName||'')+'</b></p><p>'+esc(j.routeName||'')+'</p>'+(j.gap?'<p>目標との差：'+j.gap.gap+'（'+esc(j.gap.level)+'）</p>'+hint(j.adjustNote):hint('偏差値が分からないため、標準の進め方です。'))+(j.mixedNote?hint(j.mixedNote):'')+(j.ratioNote?hint(j.ratioNote):'')+btn('教材ごとの期間を見る','page','action',{page:'upper'}))}
