 if(teacher)h+=card('月1回の見直し','<form data-form="jreview">'+select('新しい模試（任意）','mockType',[['','入れない'],'河合','東進','進研','駿台'],'')+field('偏差値','mockScore','','number','min="20" max="85" step="0.5"')+'<button class="primary">見直しを実行する</button></form>');
 if((j.reviews||[]).length)h+=card('見直しの記録',j.reviews.slice(0,3).map(r=>'<p><b>'+esc(r.at)+'</b>'+(r.level?' · '+esc(r.level):'')+'</p>'+r.changes.map(c=>'<p class="caption">・'+esc(c)+'</p>').join('')+r.warnings.map(c=>'<p class="caption warn">！'+esc(c)+'</p>').join('')).join(''));
 return h;
