const TYPE_INFO={test:['定期テスト','テストの日までに、範囲を終わらせる計画です。'],exam:['検定','検定の日までに、勉強を進める計画です。'],juken:['大学受験','志望校から逆算して、教材と期間を決める計画です。'],habit:['習慣作り','曜日ごとのメニューで、毎日少しずつ続ける計画です。'],task:['課題・提出物','提出日が近い順に、1週間の予定を作ります。']};
