function posLabel(t,p){return t.unit==='ページ'?'p.'+p:t.unit==='問題の番号'?'No.'+p:t.unit==='単語の番号'?p+'番':p+'まで'}
function partialLabel(t){return t.unit==='ページ'?'どのページまで？':'何番まで？'}
